-- 1. Amarok: la garantía de leasing ($250.000) fue devuelta: no es costo
delete from fin.costos where unidad='nom' and categoria='garantia_leasing' and origen='planilla_ig' and monto=250000;
-- 2. Corolla Cross TDCG37: compra directa NOM por $14,5 MM (4-sep-2026). Stock: sale de caja ahora y pasa a costo al venderse
insert into fin.movimientos (fecha, unidad, tipo, categoria, monto, descripcion, documento)
select '2026-09-04', 'nom', 'egreso', 'compra_stock', 14500000, 'Compra directa Toyota Corolla Cross 2024 TDCG37 (stock NOM; pasa a costo al venderse)', 'TDCG37'
where not exists (select 1 from fin.movimientos where categoria='compra_stock' and documento='TDCG37');
-- 3. Dic-2025 BlackGPS: los $3.790.898 son mensualidades, no productos
update fin.ventas set modalidad='licencia', descripcion='Mensualidades · planilla ingresos y gastos (12/2025)'
 where unidad='blackgps' and origen='planilla_ig' and fecha='2025-12-31' and modalidad='hardware';
-- 4. BlackGPS 2026: la base real de facturas es «BlackGPS Control Global» (hoja Facturacion, ene–nov).
-- Se reemplazan todas las ventas BlackGPS 2026 (facturas antiguas, totales de planilla, estimado de octubre y pedidos Asisma).
-- Excluidas: 590 (anulada) y 564 (emitida y revertida). 512 sin monto en la planilla: $233.182 (dato previo de Core).
update fin.costos set venta_id = null where venta_id in (select id from fin.ventas where unidad='blackgps' and fecha >= '2026-01-01');
delete from fin.ventas where unidad='blackgps' and fecha >= '2026-01-01';
